import java.io.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int s = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, s, pos - s);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int rows = nextInt(), cols = nextInt(), k = nextInt();
        int[] a = new int[rows * cols];
        for (int i = 0; i < a.length; i++) a[i] = nextInt();
        // extremes of p = i + j and q = i - j over all houses
        int minp = Integer.MAX_VALUE, maxp = Integer.MIN_VALUE, minq = Integer.MAX_VALUE, maxq = Integer.MIN_VALUE;
        boolean found = false;
        for (int index = 0; index < a.length; index++)
            if (a[index] != 0) {
                int i = index / cols, j = index % cols;
                found = true;
                minp = Math.min(minp, i + j);
                maxp = Math.max(maxp, i + j);
                minq = Math.min(minq, i - j);
                maxq = Math.max(maxq, i - j);
            }
        if (!found) {
            System.out.println((long) rows * cols);
            return;
        }
        long answer = 0;
        for (int index = 0; index < a.length; index++) {
            int i = index / cols, j = index % cols, p = i + j, q = i - j;
            int far = Math.max(Math.max(p - minp, maxp - p), Math.max(q - minq, maxq - q));
            if (a[index] == 0 && far <= k) answer++;
        }
        System.out.println(answer);
    }
}

